import {COOPERATION} from './cooperation.js?v=195';
import {evidenceFreshness} from './experience.js?v=195';
import * as E from './engine.js?v=195';
import {COUNTRY,COUNTRIES} from './data.js?v=195';
import {proofTitle} from './intelligence.js?v=195';
import {esc,flag,button,icon} from './ui.js?v=195';
const nation=id=>COUNTRY[id]?`${flag(id)} ${COUNTRY[id].name}`:'Non consigné';
export function exposureMarkup(a){const penalty=E.exposurePenalty(a);return `<div class="exposure-block"><div class="exposure-segments" role="meter" aria-label="Exposition" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,a.exposure)}" aria-valuetext="${a.exposure}/100 ; ${penalty?'pénalité de '+penalty+' points sur les actions sensibles':'aucune pénalité'}">${[0,20,40,60,80].map(n=>`<i class="${a.exposure>n?'filled':''} ${a.exposure>=60?'high':a.exposure>=40?'medium':'low'}"></i>`).join('')}</div><details class="exposure-card"><summary>Exposition <strong>${a.exposure}/100</strong> · ${E.exposureLabel(a)}${penalty?` · −${penalty} pts sur les actions sensibles`:''}</summary><meter min="0" max="100" value="${a.exposure}" aria-label="Exposition de l’agent"></meter><p>Traces et attention laissées par l’agent, distinctes de sa fatigue. 0–19 Discret · 20–39 Repérable au contre-espionnage mondial · 40–59 Surveillé : −6 aux actions sensibles · 60–79 Compromis : −9 sensibles / −5 enquête · 80–100 Très exposé : −12 sensibles / −10 enquête et +1 pression sur une réussite contre une cible (arrestation : +3, sans cumul). Sensibles : passage clandestin, arrestation, extraction. Enquête : collecte, localisation, préparation, intrusion. Aucune capture automatique.</p><p>Passeport +10 · acquisition d’arme +10 · drone +10 · échec +18. Réduire : profil bas −35, repos au QG −20, planque −15.</p></details></div>`;}
export function evidenceSummary(s){const f=s.factions[s.player],raw=E.evidenceQueue(s,s.player),running=raw.filter(e=>E.analysisAgent(s,s.player,e.id)).length;return `<div class="evidence-counts"><span class="good">${f.evidence.filter(e=>e.verified).length} vérifiée(s)</span><span class="pending">${raw.length-running} en attente</span><span>${running} en vérification</span><span>${f.evidence.filter(e=>e.contested).length} écartée(s)</span></div>`;}
export function evidenceRegister(s){const f=s.factions[s.player],entries=f.evidence.filter(e=>!s.suspects.find(t=>t.id===s.proofs.find(p=>p.id===e.id)?.suspect)?.arrested||e.verified).sort((a,b)=>(a.contested?2:a.verified?1:0)-(b.contested?2:b.verified?1:0));return `${evidenceSummary(s)}<p class="evidence-explanation">Pièce brute : recueillie, mais pas encore vérifiée. Pour préparer une arrestation : deux pièces indépendantes non écartées, dont au moins une vérifiée. Une falsification écartée ne compte plus. Choisissez la pièce que l’analyste doit examiner.</p>${entries.length?`<div class="table-scroll"><table><thead><tr><th>Pièce / cible</th><th>Collecte</th><th>Vérification</th><th>État / action</th></tr></thead><tbody>${entries.map(e=>{const p=s.proofs.find(x=>x.id===e.id),t=s.suspects.find(x=>x.id===p.suspect),agent=E.analysisAgent(s,s.player,e.id);return `<tr class="${evidenceFreshness(e.id)?'proof-changed':''}"><td>${button(esc(proofTitle(p)),'proof','proof-title',`data-id="${e.id}"`)}${evidenceFreshness(e.id)}<small>${t.name}</small></td><td>${nation(e.collectedBy||p.foundBy)}</td><td>${e.verified||e.contested?nation(e.verifiedBy):agent?`${esc(agent.name)} · ${agent.task.remaining} tour(s)`:'À affecter au QG'}</td><td><span class="tag ${e.contested?'danger':e.verified?'good':''}">${e.contested?'ÉCARTÉE':e.verified?'VÉRIFIÉE':agent?'EN VÉRIFICATION':'EN ATTENTE'}</span>${!e.verified&&!e.contested&&!agent?button('Vérifier cette pièce','verify','small',`data-id="${e.id}"`):''}</td></tr>`;}).join('')}</tbody></table></div>`:'<p>Aucune pièce recueillie. Activez un contact dans le pays d’une piste, puis recueillez une preuve.</p>'}`;}
export function contributors(s,t){const f=s.factions[s.player],entries=f.evidence.filter(e=>s.proofs.find(p=>p.id===e.id)?.suspect===t.id),unique=ids=>[...new Set(ids.filter(Boolean))].map(nation).join(' · ')||'Non consigné';return `<details class="contribution-list" open><summary>Contributions connues à ce dossier</summary><dl><div><dt>Preuves recueillies</dt><dd>${unique(entries.map(e=>e.collectedBy||s.proofs.find(p=>p.id===e.id).foundBy))}</dd></div><div><dt>Preuves vérifiées</dt><dd>${unique(entries.filter(e=>e.verified).map(e=>e.verifiedBy))}</dd></div><div><dt>Préparation</dt><dd>${t.prepared?nation(t.prepBy):'À préparer'}</dd></div><div><dt>Dernière localisation</dt><dd>${t.locationUntil?nation(t.locBy):'À localiser'}${t.locationUntil?` · jusqu’à T${t.locationUntil}`:''}</dd></div><div><dt>Arrestation</dt><dd>${t.arrested?nation(t.arrestedBy):'À effectuer'}</dd></div></dl><small>Provenance des informations de votre dossier. Les contributions étrangères encore secrètes ne sont pas révélées.</small></details>`;}
export function nationalPanel(s){
 const f=s.factions[s.player],next=E.governmentOptions(s,'funding').nextTurn,wait=Math.max(0,next-s.turn),countries=COUNTRIES.filter(c=>!c.power),chosen=countries.find(c=>!E.governmentOptions(s,'diplomacy',c.id).error)?.id||countries.find(c=>f.cooperation[c.id]<4)?.id,available=['funding','medical'].some(t=>!E.governmentOptions(s,t).error)||countries.some(c=>!E.governmentOptions(s,'diplomacy',c.id).error);
 const cards=[['funding','case','+5','crédits','Renforcez votre réserve.'],['diplomacy','world','+1','niveau','Améliorez une relation diplomatique.'],['medical','plus','+12','énergie','Pour tous vos agents, partout.']];
 return `<div class="government-console"><section class="panel government-overview"><div class="government-country">${flag(s.player)}<span>${esc(COUNTRY[s.player].name)}<small>Appui gouvernemental</small></span></div><div class="government-confidence"><div>${icon('seal')} Confiance <strong>${f.confidence}<small>/100</small></strong></div><div class="confidence-track ${f.confidence<10?'low':f.confidence<50?'normal':'high'}" role="meter" aria-label="Confiance gouvernementale" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${f.confidence}"><span class="confidence-fill" style="width:${f.confidence}%"></span><i class="confidence-tick tick-ten" title="10 % : 2 crédits par tour"></i><i class="confidence-tick tick-fifty" title="50 % : 3 crédits par tour"></i></div><div class="confidence-thresholds"><span style="left:10%">10 %</span><span style="left:50%">50 %</span></div><div class="confidence-income-rules"><span class="${f.confidence<10?'selected':''}">🔴 &lt; 10 % : <b>0 crédit/tour</b></span><span class="${f.confidence>=10&&f.confidence<50?'selected':''}">🟢 10–49 % : <b>2 crédits/tour</b></span><span class="${f.confidence>=50?'selected':''}">🔵 ≥ 50 % : <b>3 crédits/tour</b></span></div></div><div class="government-availability ${wait?'cooldown':available?'available':'unavailable'}">${icon(wait?'clock':available?'check':'lock')}<span><strong>${s.ended?'Campagne terminée':wait?'Prochaine faveur · T'+next:available?'Faveur disponible':'Aucune faveur disponible'}</strong><small>${wait?`Encore ${wait} tour(s)`:'Une faveur tous les 2 tours'}</small></span></div></section><section class="government-cards" aria-label="Faveurs gouvernementales">${cards.map(([type,glyph,amount,unit,desc])=>{const d=E.GOVERNMENT_FAVORS[type],o=E.governmentOptions(s,type,chosen);return `<article class="panel government-card government-${type}"><div class="government-card-top"><span class="government-symbol">${icon(glyph)}</span></div><h2>${d.name}</h2><div class="government-effect"><strong>${type==='funding'?'+'+o.gain:type==='medical'?'+'+o.energy:amount}</strong><span>${unit}</span></div><p>${desc}</p>${type==='diplomacy'?`<label class="government-target" for="governmentCountry">${icon('world')} Pays cible</label><select id="governmentCountry" ${chosen?'':'disabled'}>${countries.map(c=>`<option value="${c.id}" ${c.id===chosen?'selected':''} ${f.cooperation[c.id]>=4?'disabled':''}>${esc(c.name)} · ${COOPERATION[f.cooperation[c.id]].name}${f.cooperation[c.id]<4?' → '+COOPERATION[f.cooperation[c.id]+1].name+' · '+E.governmentOptions(s,'diplomacy',c.id).cost+' confiance':' (max.)'}</option>`).join('')}</select>`:`<small class="government-note">${type==='funding'?'Plafond de réserve : 18 crédits':`<strong class="medical-remaining">${o.medicalRemaining}/3 utilisations restantes</strong>Ne soigne pas les blessures`}</small>`}<div class="government-card-action"><span class="government-cost">${icon('seal')} <b data-government-cost>${o.cost??"—"}</b> confiance</span>${button(icon('check')+' Solliciter','government-favor','primary',`data-id="${type}" ${o.error?'disabled':''}`)}<small>${esc(o.error||'Immédiat · aucun agent mobilisé')}</small></div></article>`;}).join('')}</section><section class="panel government-footer"><div>${icon('case')}<span><strong>${f.budget}</strong> crédits</span><span>+${E.funding(f).income} / tour</span><span>Plafond 18</span></div><p>${icon('clock')} ${f.lastFavor?`Dernière faveur : ${esc(E.GOVERNMENT_FAVORS[f.lastFavor.type].name)}${f.lastFavor.country?' · '+esc(COUNTRY[f.lastFavor.country].name):''} · T${f.lastFavor.turn}`:'Aucune faveur sollicitée'}</p></section><details class="panel government-help"><summary>${icon('help')} Comprendre le soutien gouvernemental</summary><p>La confiance commence à 20 %. Chaque action avec jet de réussite rapporte +3 confiance à sa réussite, jusqu’à 100 %. Les actions automatiques (sans jet), échecs, annulations et interruptions ne rapportent rien. Chaque contribution récompensée en prestige donne aussi +2 confiance : preuve vérifiée au pays découvreur ; localisation, préparation et intervention lors de l’arrestation ; attaque déjouée au pays défenseur. Ce bonus ne peut être reçu qu’une fois par contribution. Les faveurs consomment cette confiance. Le revenu est de 0 crédit sous 10 %, 2 crédits de 10 à 49 %, et 3 crédits dès 50 %. Le niveau après résolution des actions détermine le revenu du tour.</p><p>Les trois faveurs partagent un délai : une faveur au tour 1 permet la suivante au tour 3. Le financement est limité à la place restante dans votre réserve ; son coût est de 15 confiance pour un gain allant jusqu’à 5 crédits. Une réserve pleine ne peut pas recevoir cette faveur.</p><p>Diplomatie : Hostile → Réticente : 15 confiance ; Réticente → Neutre : 15 ; Neutre → Favorable : 10 ; Favorable → Soutien total : 5. Le soutien médical coûte 25 confiance et est limité à 3 utilisations par partie et par joueur. La démarche diplomatique améliore la coopération d’un pays secondaire, sans ouvrir l’accès ni délivrer de mandat. Le soutien médical restaure jusqu’à 12 énergie à tous les agents vivants de votre équipe, au QG, à l’étranger, en déplacement ou capturés, sans soigner ses blessures ni modifier ses ordres.</p></details></div>`;
}

export function foreignProgress(s){const intel=s.factions[s.player].foreignIntel||{};return `<details class="panel cooperation-panel foreign-progress"><summary>Enquêtes des autres puissances · renseignements échangés</summary><p>État communiqué au moment du dernier échange, sans mise à jour automatique. Un nouvel échange actualise ces informations. Les ordres des agents et le contenu des pièces brutes restent privés.</p>${Object.keys(s.factions).filter(id=>id!==s.player).map(id=>{const v=intel[id];return `<article class="foreign-dossier"><h3>${nation(id)} ${v?`<small>Échange T${v.turn} · ${s.turn-v.turn} tour(s) écoulé(s)</small>`:''}</h3>${v?`<div class="table-scroll"><table><thead><tr><th>Cible</th><th>Preuves</th><th>Préparation</th><th>Localisation</th><th>Arrestation</th></tr></thead><tbody>${v.cases.map(k=>`<tr><td>${s.suspects.find(t=>t.id===k.id).name}</td><td>${k.verified} vérifiées · ${k.raw} brutes</td><td>${k.prepared?'Prête':'Non'}</td><td>${k.locationUntil>=v.turn?`Valable à l’échange, jusqu’à T${k.locationUntil}`:'Non confirmée'}</td><td>${k.arrested?'Effectuée':'Non'}</td></tr>`).join('')}</tbody></table></div>`:'<p>Progression inconnue. Aucun état reçu.</p>'}</article>`;}).join('')}</details>`;}

export function energyHelp(a){const energy=100-a.fatigue,penalty=a.fatigue>=75?20:a.fatigue>=50?10:0;return `<details class="exposure-card energy-card"><summary>Énergie · effets sur les actions${penalty?` · −${penalty} pts`:''}</summary><p>51–100 énergie : aucun malus.<br>26–50 : −10 points de réussite.<br>0–25 : −20 points de réussite.</p><p>Ces malus concernent les actions avec un jet de réussite. Voyage sous passeport, repos, soins et profil bas restent automatiques.</p><p>À 0 énergie, la plupart des missions sont indisponibles. Restent possibles : voyage sous passeport, repos au QG, soins, profil bas, trouver une planque et repos en planque.</p><p>Repos au QG : +50 énergie · planque : +30 · profil bas : +10 · soins : +40. Secourisme soigne automatiquement une blessure en fin de tour dans le même pays, sans énergie supplémentaire. Endurance réduit de 25 % la fatigue des voyages, passages clandestins, localisations, arrestations et extractions.</p></details>`;}

export function exposureBar(a){const n=Math.max(0,Math.min(100,a.exposure));return `<div class="fatigue exposure-meter"><span>${n}/100 exposition · ${E.exposureLabel(a)}</span><i role="meter" aria-label="Exposition" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${n}"><b class="${n>=40?'warm':''}" style="width:${n}%"></b></i></div>`;}
